#ifndef CSOUNDSET_H
#define CSOUNDSET_H

#include "CResHelper.h"
#include "resssf.h"
#include "exostring.h"
#include "exoresman.h"

struct STR_RES;

// One creature's .ssf sound set: a resource handle and nothing else.
class CSoundSet : public CResHelper<CResSSF, 2060> {
public:
    CSoundSet(const CResRef& resRef);
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 2 slots
    virtual ~CSoundSet();
    // </VTABLE-GEN>

    // Returns 0/1. Slot ids are 1-based and bounded at 28; an all-ones ref means the creature has no
    // sound for that slot.
    int GetStrres(unsigned short nStrres, STR_RES& strRes);
};

// Indexes soundset.2da, mapping a creature's SoundSetFile row to a resref, a gender and a name
// string-ref.
class CSoundSetList {
public:
    CSoundSetList();
    ~CSoundSetList();

    CResRef       GetSoundSet(unsigned short nSoundSet);
    unsigned char GetGender(unsigned short nSoundSet);
    CExoString    GetName(unsigned short nSoundSet);

    unsigned short m_nCount;
    CResRef*       m_paResRefs;
    unsigned char* m_panGenders;
    int*           m_panNameStrRefs;
};

#endif // CSOUNDSET_H
